from lib import *
M=mcq;F=tf;S=short
chapter(4,'evs','how-things-work','How Things Work',
 ('Meera spins a coin','Meera and Dhruv love finding out how things work. One Sunday Meera spun a coin and watched it slow down and begin to shake. Then they tried spinning many other objects to see which ones spin well.'),
 [('Spinning things',['Some objects like coins and bangles spin, while others like erasers do not spin properly.','As a coin slows down, it starts to shake, and we can wonder why and try to explain it ourselves.','We can make spinners from cardboard, toothpicks and an empty pen tube and record what we see.']),
  ('Trying out changes',['We change one thing at a time, such as putting the toothpick at the centre or away from the centre, using a square or a circular spinner, and then see whether it spins.','Spinners that are balanced around the centre usually spin better.','The book says it is enough to explore and give possible explanations; there is no need for a perfect scientific answer yet.']),
  ('Thinking like explorers',['We use things every day, like a pencil to write or a bag to carry books, and we can ask how they work and how they could work better.','Record what you observe and what you wonder, then test your idea.'])],
 [], ('Tell how you would test which spinner spins best.',['Change one thing at a time','Observe whether it spins','Give your own explanation'],['All objects spin equally well']),
 ['Some objects spin and some do not.','Changing one thing at a time shows what matters.','Observe, wonder and test.'],
 [M('1',1,'What happens to a coin as it slows down?','It begins to shake',[('It grows bigger','Size does not change'),('It melts','Spinning does not melt a coin')],'Meera saw the coin shake as it slowed down.'),
  F('2',1,'All objects spin equally well.',False,'Coins and bangles spin but erasers do not spin properly.'),
  M('3',1,'Where can the toothpick be placed in a spinner to test?','At the centre or away from the centre',[('Only outside','Both positions are tested'),('Nowhere','The toothpick is the spindle')],'The children test the toothpick at the centre and away from it.'),
  M('4',2,'Which object is not likely to spin properly?','Eraser',[('Coin','It spins'),('Bangle','It spins')],'Some objects like erasers do not spin properly.'),
  S('5',2,'What do we record in the table when we spin objects?',['what we observe','observations'],'We write what we observe and what we wonder.'),
  F('6',3,'We should change one thing at a time while testing a spinner.',True,'Changing one thing at a time shows which change makes the difference.')])
chapter(4,'evs','how-things-are-made','How Things are Made',
 ('Pihu and the newspaper','Pihu saw a newspaper picture saying that recycling paper saves trees. Her mother explained that paper is made from trees, and they decided to make recycled paper at home.'),
 [('Paper comes from trees',['Drawing books, newspapers, paper napkins and chart papers are all made from trees.','A pot that looked like paper but felt rough was made from recycled paper.','Recycling paper saves trees.']),
  ('Make recycled paper',['Collect old newspapers, a few fenugreek seeds (methi) and water.','Tear the newspaper into small pieces, soak them with a little methi in water overnight; the seeds bind the paper.','Blend or mash the soaked paper and seeds into a wet paste.','Spread the paste on a flat base, roll it into thin sheets and leave them to dry. Your recycled paper is ready.']),
  ('Colours from nature',['Cut the paper into equal pieces and colour them with natural things like turmeric, spinach, beetroot and henna.','Use the same quantity each time and note the colour and whether it is dull or bright, for example turmeric gives a dull yellow.','We should not waste paper: use both sides and reuse and recycle.'])],
 [], ('Explain how to make recycled paper at home.',['Soak old paper with methi seeds','Mash and roll into sheets','Dry them'],['Paper is made from plastic']),
 ['Paper is made from trees.','Recycled paper is made from old paper soaked and mashed with methi seeds.','Natural colours can be made from turmeric, spinach, beetroot and henna.'],
 [M('1',1,'What is paper made from?','Trees',[('Stones','Paper is not made of stones'),('Metal','Paper is not made of metal')],'Drawing books and newspapers are made from trees.'),
  M('2',1,'Why are methi seeds added to the paper pulp?','They bind the paper',[('To colour it blue','They are used for binding'),('To make it smell','Binding is their job')],'Fenugreek seeds work as a binding material.'),
  F('3',1,'Recycling paper helps save trees.',True,'Using old paper again means fewer trees are cut.'),
  M('4',2,'Which natural ingredient gives yellow colour?','Turmeric',[('Beetroot','It gives a red-pink colour'),('Spinach','It gives green')],'The table shows turmeric gives yellow, dull.'),
  S('5',2,'What do we do with the paste after spreading it?',['roll it into sheets','roll out','dry it'],'We roll it into thin sheets and leave it to dry.'),
  F('6',3,'We should use the same amount of each natural colour in the experiment.',True,'Using the same quantity makes the test fair.')])
chapter(4,'evs','different-lands-different-lives','Different Lands, Different Lives',
 ('Holiday stories','After holidays, Chandni talked about a beach in Odisha, Ritika about the Rajasthan desert, Gurpreet about his grandparents\' farmland in Amritsar and Nayan about the mountains of Sikkim. Each place had its own land, food, clothes and way of living.'),
 [('Places are different',['India has mountains, plains, coasts and deserts, and each region has its own plants, animals, food, clothes and activities.','Friends can compare their holiday places and tell what is special about each.']),
  ('Plains of Punjab',['Gurpreet\'s grandmother welcomes him with the words Jee aayan nu puttar.','The plains of Amritsar have large fields and rich fertile soil, and many people do farming.','Their favourite food is makki di roti, made with corn flour, with sarson da saag.']),
  ('Coast, desert and mountains',['Near the sea there are trees that grow near the coast and people have special ways to stay safe, because cyclones can cause damage and communities must be prepared.','In a desert people dress and travel in ways suited to the heat, and animals like camels help.','In the mountains people wear warm traditional clothes, animals like yak help, and landslides are common in the rainy season, so people must be careful.','People live in ways suited to their land, and every way of life deserves respect.'])],
 [], ('Compare two places you know.',['Land, food, clothes differ','People adapt to their land','Respect all ways of life'],['Everyone lives the same way']),
 ['Mountains, plains, coasts and deserts are different lands.','Food, clothes and work depend on the land.','Communities prepare for cyclones and landslides.'],
 [M('1',1,'Who visited the desert of Rajasthan?','Ritika',[('Chandni','She visited a beach in Odisha'),('Nayan','He visited the mountains of Sikkim')],'Ritika described the desert of Rajasthan.'),
  M('2',1,'What is made with corn flour in Punjab?','Makki di roti',[('Dosa','Dosa is made with rice and dal'),('Idli','Idli is a rice dish')],'Makki di roti is made with corn flour.'),
  F('3',1,'People everywhere live in exactly the same way.',False,'Land, weather, food and clothes shape how people live.'),
  M('4',2,'Which animal helps people in the mountains?','Yak',[('Camel','Camels help in deserts'),('Cow only','Yaks are mountain animals')],'The chapter mentions animals like the yak in the mountains.'),
  S('5',2,'What kind of soil do the plains of Amritsar have?',['fertile','rich and fertile','rich'],'The soil is rich and fertile so farming is common.'),
  F('6',3,'Communities can prepare to stay safe from cyclones and landslides.',True,'Being prepared reduces harm from natural events.')])
chapter(4,'evs','our-sky','Our Sky',
 ('Looking up','The sky looks different in the morning, afternoon and night. The Sun seems to change colour and the Moon seems to change shape. Birds, animals, plants and people also behave differently at different times of the day.'),
 [('The sky through the day',['In the morning the sky can look orange, in the afternoon the sunlight is strong, and at night we see the Moon and stars.','Animals, plants and people change what they do at sunrise, noon and sunset.']),
  ('The Sun',['The brightest object in the sky is the Sun. It is so bright that other stars cannot be seen when it is in the sky.','The Sun gives us light and heat.','It appears to rise in the morning, move up till overhead, then slowly go down on the other side and disappear.']),
  ('Shadows',['Your shadow moves along with you; if you run it runs and if you pose it poses.','You can try this with a torch and a stick: hold the stick still and move the torch to see how the shadow changes.','Observe and share what changes at sunrise and sunset at your home.'])],
 [], ('Tell what changes in the sky and around us during a day.',['Sun rises and sets','Sky colour changes','Shadows change'],['The Sun is dark at noon']),
 ['The Sun is the brightest object in the sky.','The Sun seems to rise, move overhead and set.','Shadows change when the light moves.'],
 [M('1',1,'What is the brightest object in the sky?','The Sun',[('The Moon','The Moon is bright at night only'),('A star','The Sun hides the stars')],'The Sun gives light and heat and hides the stars by day.'),
  F('2',1,'The sky looks the same all day.',False,'It changes in the morning, afternoon and night.'),
  M('3',1,'What gives us light and heat?','The Sun',[('The Moon','It does not give heat'),('Clouds','They give shade')],'The Sun gives us light and heat.'),
  M('4',2,'When can we see the Moon and stars?','At night',[('At noon','The Sun is too bright'),('In the morning only','Stars are seen at night')],'The Sun hides stars by day, so they appear at night.'),
  S('5',2,'What moves along with us when we walk in the sun?',['shadow','our shadow','the shadow'],'A shadow follows us because we block the sunlight.'),
  F('6',3,'The Sun appears to rise in the morning and set in the evening.',True,'It seems to move up, overhead, then down and disappear.')])
